<template><Teleport to="body"><Transition name="modal"><div v-if="modelValue" class="backdrop" @click.self="close"><section ref="panel" role="dialog" aria-modal="true" :aria-labelledby="id" tabindex="-1" :class="{wide}" class="modal"><header><div><span class="fm-kicker">{{kicker}}</span><h2 :id="id">{{title}}</h2><p v-if="description">{{description}}</p></div><button aria-label="关闭弹窗" @click="close">×</button></header><main><slot/></main><footer v-if="$slots.actions"><slot name="actions"/></footer></section></div></Transition></Teleport></template>
<script setup>import{nextTick,onBeforeUnmount,onMounted,ref,watch}from"vue";const props=defineProps({modelValue:Boolean,title:String,kicker:String,description:String,wide:Boolean});const emit=defineEmits(["update:modelValue"]),panel=ref(),id=`modal-${Math.random().toString(36).slice(2)}`;function close(){emit("update:modelValue",false)}function key(e){if(e.key==="Escape")close()}watch(()=>props.modelValue,async v=>{document.body.style.overflow=v?"hidden":"";if(v){await nextTick();panel.value?.focus()}});onMounted(()=>document.addEventListener("keydown",key));onBeforeUnmount(()=>{document.removeEventListener("keydown",key);document.body.style.overflow=""});</script>
<style scoped>.backdrop{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:20px;background:rgba(0,0,0,.34);backdrop-filter:blur(5px)}.modal{width:min(480px,100%);max-height:calc(100dvh - 40px);overflow:auto;padding:28px 30px 24px;border:1px solid var(--fm-line);border-radius:16px;background:var(--fm-bg-card);box-shadow:var(--fm-modal-shadow)}.modal.wide{width:min(760px,100%)}header{display:flex;justify-content:space-between;gap:16px}h2{margin:6px 0;font-size:21px}header p{margin:0;color:var(--fm-ink-soft);font-size:13px}header button{width:34px;height:34px;border-radius:9px;background:var(--fm-bg-warm);font-size:22px}main{margin-top:20px}footer{display:flex;justify-content:flex-end;gap:8px;margin-top:20px;padding-top:16px;border-top:1px solid var(--fm-line-soft)}.modal-enter-active,.modal-leave-active{transition:opacity .16s}.modal-enter-from,.modal-leave-to{opacity:0}@media(max-width:560px){.backdrop{align-items:end;padding:10px}.modal{max-height:calc(100dvh - 20px);padding:22px}}</style>
